public bool IsKyCuoc
{
	get { return kyCuocEnabled; }
	set
	{
		lock (kyCuocLock)
		{
			if (kyCuocEnabled == value) return;
			kyCuocEnabled = value;
			ResetKyCuocSession();
			if (value) InitializeKyCuocSession();
		}
	}
}

